from __future__ import absolute_import
import logging
from selenium.common.exceptions import TimeoutException, NoSuchElementException
from selenium.webdriver.common.by import By
from taf.ul.oam.selenium_rap_manager.common import LocalBasicPage
from taf.ul.oam.selenium_rap_manager.exceptions import FailedLoginException


class LoginPage(LocalBasicPage):

    def __init__(self, driver):
        super(LoginPage, self).__init__(driver)

    def login(self, username, password, after_reset=False):
        """
        Perform user login with given credentials. If site returns warning about
        incompatible browser click proceed link.

        :param username:
        :param password:
        :param after_reset: allow login to fail. New vesions of software performs login automatically.
        :return: SiteManagementPage object
        """
        try:
            self.click_continue_if_needed()
            self.insert_username(username)
            self.insert_password(password)
            self.click_login_button()
            self._wait_for_element_by((By.ID, "logout-link"), 10)
        except NoSuchElementException:
            if not after_reset:
                raise
        except TimeoutException:
            raise FailedLoginException("Login failed")

    def click_continue_if_needed(self, timeout=10):
        """
        Proceed to next page if incompatible browser warning appeared

        :param timeout: search timeout
        """
        try:
            id = "continue"
            self._wait_for_element_by((By.ID, id), timeout)
            elem = self._driver.find_element_by_id(id)
            elem.click()
        except TimeoutException:
            logging.info("no continue dialog box")

    def insert_username(self, username):
        """
        Inserts given login to login field

        :param username: user name
        """
        self.insert_text_to_field("applicationLoginUsername", username)

    def insert_password(self, password):
        """
        Inserts given password to password field

        :param password: user password
        """
        self.insert_text_to_field("applicationLoginPassword", password)

    def click_login_button(self):
        """
        Clicks login button
        """
        elem = self._driver.find_element_by_id("applicationLoginButton")
        elem.click()
